#!/usr/bin/env python3
"""MFRE (Fase 47 inc.C, D25): complete the Brazilian Portuguese catalog
(launcher/lang/pt-br.json).

The 489 strings pt-br.json lacked (report: `python3 tools/mfre_lang_report.py
--dump pt-br`), in one alphabetical batch, validated the way `i18n::tests` does:
the {holes} of a value match its key's, and no value is empty. The catalog stays
sparse on purpose (philosophy of patch 0006); after this it is complete, like es.

    python3 tools/mfre_lang_pt_br.py --report   # counts only, nothing written
    python3 tools/mfre_lang_pt_br.py --apply    # write pt-br.json

Terminology follows the existing catalog: Configurações (Settings), Início (Home),
Armazenamento (Storage), compilação/compilar (build), carregador (loader), lixeira
(Trash), pacote de recursos/dados/shaders, Mais recente (Latest), mods nativos.
Horizon stays Horizon where it names the upstream project, its registry or its
services, as the existing catalog does; the fork and its launcher say MineForge.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PT_BR = ROOT / "launcher" / "lang" / "pt-br.json"

